First, let's update `src/stats.js` to remove the import statement for testing purposes since we will run the tests separately:

```javascript
export function mean(values) {
  if (values.length === 0) throw new Error("empty");
  return values.reduce((a, b) => a + b, 0) / values.length;
}

export function median(values) {
  const sortedValues = [...values].sort((a, b) => a - b);
  const half = Math.floor(sortedValues.length / 2);
  if (sortedValues.length % 2 === 0) return (sortedValues[half - 1] + sortedValues[half]) / 2;
  else return sortedValues[half];
}
```

Next, let's write the test script in `test/stats-test.js`:

```javascript
// test/stats-test.js

const { mean, median } = require('./stats');

const testMedian = () => {
  const testData = [1, 3, 5, 7, 9];
  console.assert(median(testData) === 5, 'The median of an odd number of values should be the middle value');
  testData.push(11);
  console.assert(median(testData) === (5 + 7) / 2, 'The median of an even number of values should be the average of the two middle values');
};

testMedian();
```

Now let's run this test script using Node.js:

